package cuvee.transform

import util.Name
import cuvee.pipe.Transform
import cuvee.core._

// flattening of constrained Horn clauses as generated by Horn:
// arguments of the predicates whose sort is a non-recursive datatype with a single constructor,
// e.g. a record, are replaced by the fields of the datatype, recursively,
// such that the predicates range over the fields only;
// the bound variables of such sorts are replaced by the constructor applied to fresh variables for the fields,
// which makes selectors and testers applied to them trivial,
// and equations between values of such sorts become conjunctions of equations between their fields;
// the predicates are the uninterpreted functions with a boolean result,
// i.e., those declared without definition that are neither constructors nor selectors
object Flat extends Transform:
  def apply(prefix: List[Cmd], cmds: List[Cmd], last: Cmd, state: State): List[Cmd] =
    for cmd <- cmds
    yield flat(state, cmd)

  def flat(state: State, cmd: Cmd): Cmd =
    cmd match
      case DeclareFun(fun, attrs) if isPredicate(state, fun) =>
        DeclareFun(predicate(state, fun), attrs)

      case Assert(justify, params, phi, attrs) =>
        Assert(justify, params, flat(state, phi), attrs)

      case _ =>
        cmd

  // the single constructor of a non-recursive datatype `typ` with its selectors,
  // whose types are instantiated by the arguments of `typ`
  def record(state: State, typ: Type): Option[(Fun, List[Fun])] =
    typ match
      case Sort(con, args) if state.datatypes.contains(con.name) && !recursive(state, con) =>
        state.datatypes(con.name) match
          case Datatype(_, List((constr, sels))) =>
            Some((constr, sels))

          case _ =>
            None

      case _ =>
        None

  // the sort `con` occurs in the fields of its datatype, possibly through other datatypes
  def recursive(state: State, con: Con): Boolean =
    // the types of the fields of all constructors of a datatype
    def fields(con: Con): List[Type] =
      state.datatypes.get(con.name) match
        case Some(Datatype(_, constrs)) =>
          for (_, sels) <- constrs; sel <- sels yield sel.res

        case None =>
          Nil

    def reaches(typ: Type, seen: Set[Con]): Boolean =
      typ match
        case Sort(`con`, _) =>
          true

        case Sort(other, args) =>
          args.exists(reaches(_, seen)) || (!seen.contains(other) && fields(other).exists(reaches(_, seen + other)))

        case _ =>
          false

    fields(con).exists(reaches(_, Set(con)))

  def isRecord(state: State, typ: Type) =
    record(state, typ).isDefined

  // uninterpreted predicates with arguments to be flattened
  def isPredicate(state: State, fun: Fun): Boolean =
    val key = (fun.name, fun.arity)
    val selectors =
      for
        data <- state.datatypes.values;
        (constr, sels) <- data.constrs;
        sel <- sels
      yield sel

    fun.res == Sort.bool
      && fun.params.isEmpty
      && fun.args.exists(isRecord(state, _))
      && !state.fundefs.contains(key)
      && !selectors.exists(_ == fun)

  // the predicate with flattened formal parameters, named after the parameter and the selectors
  def predicate(state: State, fun: Fun): Fun =
    val Fun(name, params, formals, res) = fun
    Fun(name, params, formals.flatMap(leaves(state, _)), res)

  // the variables for the fields of `x`, named x_sel, recursively for nested records
  def leaves(state: State, x: Var): List[Var] =
    record(state, x.typ) match
      case None =>
        List(x)

      case Some((constr, sels)) =>
        for
          sel <- sels;
          leaf <- leaves(state, Var(Name(x.name.name + "_" + sel.name.name, x.name.index), field(sel, x)))
        yield leaf

  // the type of `sel` applied to `arg`
  def field(sel: Fun, arg: Expr): Type =
    App(sel, List(arg)).typ

  // a value of type `typ` in terms of the variables for its fields, together with the unused variables
  def build(state: State, typ: Type, leaves: List[Var]): (Expr, List[Var]) =
    record(state, typ) match
      case None =>
        (leaves.head, leaves.tail)

      case Some((constr, sels)) =>
        val x = Var("x", typ)
        val (args, rest) =
          sels.foldLeft((List.empty[Expr], leaves)):
            case ((args, leaves), sel) =>
              val (arg, rest) = build(state, field(sel, x), leaves)
              (args :+ arg, rest)

        (App(constr, args), rest)

  // the fields of `expr`, recursively for nested records
  def parts(state: State, expr: Expr): List[Expr] =
    record(state, expr.typ) match
      case None =>
        List(expr)

      case Some((constr, sels)) =>
        expr match
          case App(`constr`, _, _, args) =>
            args.flatMap(parts(state, _))

          case _ =>
            sels.flatMap(sel => parts(state, App(sel, List(expr))))

  // bound variables of record sorts are replaced by the constructor applied to fresh variables for the fields,
  // which are fresh if their names clash with the other variables of the binder
  def bind(state: State, bound: List[Var], body: Expr): (List[Var], Expr) =
    val taken = (bound ++ body.free).map(_.name).toSet

    val pairs =
      for x <- bound
      yield
        val leaves_ = leaves(state, x)
        if leaves_ == List(x)
        then (leaves_, None)
        else
          val leaves__ = if leaves_.exists(y => taken.contains(y.name)) then leaves_.fresh else leaves_
          val (expr, _) = build(state, x.typ, leaves__)
          (leaves__, Some(x -> expr))

    val (bound_, substs) = pairs.unzip
    val (xs, exprs) = substs.flatten.unzip
    val su = Subst.from(xs, exprs)
    (bound_.flatten, su(body))

  def flat(state: State, expr: Expr): Expr =
    expr match
      case Bind(quant, bound, body) =>
        val (bound_, body_) = bind(state, bound, body)
        Bind(quant, bound_, flat(state, body_))

      case Let(bound, args, body) =>
        Let(bound, args.map(flat(state, _)), flat(state, body))

      case App(fun, _, _, args) if isPredicate(state, fun) =>
        val args_ = args.map(flat(state, _))
        App(predicate(state, fun), args_.flatMap(parts(state, _)))

      case Eq(left, right) if isRecord(state, left.typ) =>
        val left_ = parts(state, flat(state, left))
        val right_ = parts(state, flat(state, right))
        And(Eq(left_, right_))

      case App(fun, inst, typ, args) =>
        val args_ = args.map(flat(state, _))
        select(state, App(fun, inst, typ, args_))

      case Distinct(exprs) =>
        Distinct(exprs.map(flat(state, _)))

      case Is(arg, fun) =>
        val arg_ = flat(state, arg)
        record(state, arg_.typ) match
          case Some((constr, _)) => if constr == fun then True else False
          case None              => Is(arg_, fun)

      case As(arg, typ) =>
        As(flat(state, arg), typ)

      case _: Var | _: Lit =>
        expr

  // selectors applied to the constructor of a record
  def select(state: State, expr: Expr): Expr =
    expr match
      case App(sel, _, _, List(arg)) =>
        record(state, arg.typ) match
          case Some((constr, sels)) if sels.contains(sel) =>
            arg match
              case App(`constr`, _, _, args) => args(sels.indexOf(sel))
              case _                         => expr

          case _ =>
            expr

      case _ =>
        expr
